SELECT SAL * 12 AS ANNUAL
FROM EMP
WHERE ANNUAL > 30000;

SELECT DEPTNO, ENAME, SUM(SAL)
FROM EMP
GROUP BY DEPTNO;

SELECT *
FROM EMP E INNER JOIN DEPT D
  ON E.DEPTNO = D.DEPTNO;

SELECT *
FROM DEPT D LEFT OUTER JOIN EMP E
  ON D.DEPTNO = E.DEPTNO;

SELECT *
FROM EMP E FULL OUTER JOIN DEPT D
  ON E.DEPTNO = D.DEPTNO;

SELECT E.ENAME, M.ENAME
FROM EMP E JOIN EMP M
  ON ( ____________ );

SELECT E.ENAME, G.GRADE
FROM EMP E, SALGRADE G
WHERE E.SAL BETWEEN G.LOSAL AND G.HISAL;

SELECT *
FROM DEPT D, EMP E
WHERE D.DEPTNO = E.DEPTNO(+);

SELECT V FROM A
UNION
SELECT V FROM B;

SELECT V FROM A
UNION ALL
SELECT V FROM B;

SELECT V FROM A
INTERSECT
SELECT V FROM B;

SELECT V FROM A
MINUS
SELECT V FROM B;

SELECT SAL,
       SUM(SAL) OVER (ORDER BY SAL) AS CUM
FROM EMP;

SELECT SAL,
       LAG(SAL, 1) OVER (ORDER BY SAL) AS PREV
FROM EMP;

